import {
  Col,
  Row,
  Space,
  Table,
  Tag,
  DatePicker,
  Card,
  Button,
  message,
  Spin,
} from "antd";
import Search from "antd/es/input/Search";
import React, { useEffect, useState } from "react";
import DetailModal from "../detail/DetailModal";
import {
  FileDoneOutlined,
  EditOutlined,
  SyncOutlined,
} from "@ant-design/icons";
import moment from "moment";
import MotionHoc from "../../../utils/MotionHoc";
import { Link } from "react-router-dom";
import {
  baseUrl,
  GET_JOB_IN_PROGRESS,
  GET_LAWSUIT_DETAIL,
  HEADERS_EXPORT,
} from "../../API/apiUrls";

//use redux
import { useSelector } from "react-redux";
import axios from "axios";
import {
  AWAITING_JUDMENT,
  ENFORCEMENT,
  INDICT,
  NOTICE,
} from "../../../utils/constant/StatusConstant";
import DateCustom from "../../../hook/DateCustom";
import InvestigateAssetsDetail from "./modal/InvestigateAssetsDetail";

const Main = () => {
  const [convertDateThai] = DateCustom();

  const [isModal, setIsModal] = useState(false);
  const [isModalInvestigateAssetsDetail, setIsModalInvestigateAssetsDetail] =
    useState(false);
  const [isModalDocument, setIsModalDocument] = useState(false);
  const [isModalUpdate, setIsModalUpdate] = useState(false);
  const [arrayTable, setArrayTable] = useState();
  const [dataArr, setDataArr] = useState();
  const profileRedux = useSelector((state) => state.authReducer.profile);
  const { RangePicker } = DatePicker;
  const [loading, setLoading] = useState();
  const [dataModal, setDataModal] = useState();
  const [tableLength, setTableLength] = useState(0);
  const [dataLoadLawSuit, setDataLoadLawSuit] = useState(null);
  const [dataLoadJob, setDataLoadJob] = useState(null);

  console.log(profileRedux.id);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async (data) => {
    setLoading(true);
    console.log(data);
    let loadJob;
    try {
      const [lawsuitRes, jobInProgress] = await Promise.all([
        axios.get(`${baseUrl}${GET_LAWSUIT_DETAIL}`, {
          HEADERS_EXPORT,
        }),
        axios.get(`${baseUrl}${GET_JOB_IN_PROGRESS}`, {
          HEADERS_EXPORT,
        }),
      ]);

      if (jobInProgress.status === 200) {
        if (jobInProgress.data) {
          if (jobInProgress.data) {
            setLoading(false);
            setDataLoadJob(jobInProgress.data);
            loadJob = jobInProgress.data;
          }
        } else {
          setArrayTable([]);
          message.error("ไม่พบข้อมูลเงิน");
        }
      }
      let i = 1;
      if (lawsuitRes.status === 200) {
        console.log("lawsuitRes", lawsuitRes.data);
        const newData = lawsuitRes.data.map((item) => ({
          ...item,
          key: i++,
        }));
        setDataLoadLawSuit(lawsuitRes.data);
        filterData(loadJob, newData);
      } else {
        message.error("ไม่พบข้อมูลคดี");
      }
    } catch (error) {
      console.error("Error loading data:", error);
      message.error(`ไม่พบข้อมูล: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };
  console.log("dataArr", dataArr);

  const filterData = (data, dataLoad) => {
    if (Array.isArray(data)) {
      const mergedData = dataLoad.map((item) => {
        const matchingLawsuit = data.filter(
          (loan) => loan.id === item.LOAN_ID // ใช้ LOAN_ID หรือ id ตามต้องการ
        );
        // ถ้ามี matchingLawsuit จะรวมข้อมูล
        return {
          ...item,
          ...(matchingLawsuit ? { lawsuitData: matchingLawsuit } : {}),
        };
      });

      const newData = mergedData.filter(
        (item) => item?.lawsuitData[0].MAIN_STATUS_ID <= INDICT
      );
      console.log("newDataLawsuit 11", data);
      console.log("newDataLawsuit 11", newData);
      console.log("matchingLawsuit 11", mergedData);

      console.log("mergedData", mergedData);
      setArrayTable(newData);
      setDataArr(newData);
      setTableLength(newData.length);
      console.log(newData);
      console.log("Length of filtered data:", newData.length);
    } else {
      console.error("data is not an array or is undefined");
      setTableLength(0);
    }
  };

  const search = (event) => {
    console.log("query--->", event.target.value);
    onSearch(event.target.value);
  };

  const onSearch = (value) => {
    let result = dataArr.filter((item) => item.CONTNO.includes(value));
    setArrayTable(result);
  };

  const onSearchByDate = (startDate, endDate) => {
    console.log(endDate[0]);
    console.log(endDate[1]);

    const start = moment(endDate[0], "YYYY-MM-DD");
    const end = moment(endDate[1], "YYYY-MM-DD");

    const timestampStart = start.valueOf();
    const timestampEnd = end.valueOf();

    if (startDate && endDate) {
      const selectSearch = dataArr.filter((item) => {
        const date = moment(item.DATE, "YYYY-MM-DD");
        const itemDate = date.valueOf();
        if (itemDate >= timestampStart && itemDate <= timestampEnd) {
          return item;
        } else {
          return null;
        }
      });
      setArrayTable(selectSearch);
    } else {
      setArrayTable(dataArr);
    }
  };

  const handleUpdateData = (data) => {
    console.log("data---->update", data);
    console.log("dataArr", dataArr);
    if (data) {
      const result = dataArr.map((item) => {
        if (item.id === data.id) {
          return { ...data };
        } else {
          return { ...item };
        }
      });
      console.log("result", result);
      setDataArr(result);
      setArrayTable(result);
    } else {
      loadData();
      console.log("handleUpdateData loadData");
    }
  };

  //ทำ render record ของตาราถ้าใช้ logic เยอะ
  const renderDataAsset = (record) => {
    //ส่งค่า null ออกไปถ้า record นี่ยังไม่มี
    console.log(record.investigate_before_status);
    if (record.investigate_before_status === null) {
      return null;
    }

    console.log(record);

    let color = record.investigate_before_status > 0 ? "green" : "red";

    return (
      <Tag color={color} key={record.id} style={{ textAlign: "center" }}>
        {record.investigate_before_status === 1 ? "เจอทรัพย์" : "ไม่เจอทรัพย์"}
      </Tag>
    );
  };

  const columns = [
    {
      title: "ลำดับ",
      dataIndex: "key",
      key: "key",
      align: "center",
      width: "10%",
      render: (text, object, key) => key + 1,
      sorter: {
        compare: (a, b) => a.key - b.key,
        multiple: 5,
      },
    },
    {
      title: "เลขที่สัญญา",
      dataIndex: "CONTNO",
      key: "CONTNO",
      align: "center",
      render: (text, record) => (
        <>
          {record.lawsuitData[0].CONTNO ? record.lawsuitData[0].CONTNO : null}
        </>
      ),
    },
    {
      title: "ชื่อ-นามสกุล",
      dataIndex: "CUSTOMER_TNAM",
      key: "CUSTOMER_TNAM",
      align: "center",
      render: (text, record) => (
        <>
          {record.lawsuitData[0].CUSTOMER_TNAME
            ? record.lawsuitData[0].CUSTOMER_TNAME
            : null}{" "}
          {record.lawsuitData[0].CUSTOMER_FNAME
            ? record.lawsuitData[0].CUSTOMER_FNAME
            : null}{" "}
          {record.lawsuitData[0].CUSTOMER_LNAME
            ? record.lawsuitData[0].CUSTOMER_LNAME
            : null}
        </>
      ),
    },
    {
      title: "สถานะการสืบทรัพย์",
      align: "center",
      render: (record) => <>{renderDataAsset(record)}</>,
    },
  ];

  return (
    <>
      <Card>
        <Spin spinning={loading} size="large" tip=" Loading... ">
          <Row>
            <Col span={"24"} style={{ textAlign: "end", marginBottom: "10px" }}>
              <Space direction="vertical" size={12}>
                <RangePicker
                  size="large"
                  style={{ marginRight: "10px" }}
                  onChange={onSearchByDate}
                />
              </Space>
              <Search
                placeholder="ค้นหาสัญญา"
                onChange={search}
                enterButton
                style={{
                  width: 200,
                }}
                size="large"
              />
            </Col>
            <Col span={"24"}>
              <Table
                size="small"
                columns={columns}
                dataSource={arrayTable}
                scroll={{ x: 850 }}
                footer={() => <p>จำนวนสัญญาทั้งหมด {tableLength}</p>}
                expandable={{
                  expandedRowRender: (record) => (
                    <p style={{ margin: 0 }}>
                      {/* {!record.investigate_before_status ? ( */}
                      <Button
                        style={{
                          boxShadow: "0 4px 3px",
                          marginRight: "10px",
                        }}
                        onClick={() => {
                          setIsModalInvestigateAssetsDetail(true);
                          setDataModal(record);
                        }}
                      >
                        <EditOutlined
                          style={{ color: "orange", fontSize: "16px" }}
                        />
                      </Button>
                      {/* ) : ( */}
                      <>
                        <Button
                          style={{
                            boxShadow: "0 4px 3px",
                            marginRight: "10px",
                          }}
                          onClick={() => {
                            setIsModalDocument(true);
                          }}
                        >
                          <FileDoneOutlined
                            style={{ color: "green", fontSize: "16px" }}
                          />
                        </Button>
                      </>
                      {/* )} */}
                    </p>
                  ),
                  rowExpandable: (record) => record.name !== "Not Expandable",
                }}
              />
            </Col>
          </Row>
        </Spin>
      </Card>
      {isModal ? <DetailModal open={isModal} close={setIsModal} /> : null}
      {isModalInvestigateAssetsDetail ? (
        <InvestigateAssetsDetail
          open={isModalInvestigateAssetsDetail}
          close={setIsModalInvestigateAssetsDetail}
          dataDefualt={dataModal}
          funcUpdateStatus={handleUpdateData}
        />
      ) : null}
      {/* {isModalDocument ? (
        <DocumentNotice open={isModalDocument} close={setIsModalDocument} />
      ) : null} */}
      {/* {isModalUpdate ? (
        <UpdateStatusInvestigateAssets
          open={isModalUpdate}
          close={setIsModalUpdate}
          dataDefualt={dataModal}
          funcUpdateStatus={handleUpdateData}
        />
      ) : null} */}
    </>
  );
};

const InvestigateAssetsBefore = MotionHoc(Main);
export default InvestigateAssetsBefore;
